Think: Process each file listed in temp_workspace/file_list.txt and extract strictly integer tokens into temp_workspace/ints_<basename>.txt and mixed alphanumeric tokens into temp_workspace/verify_<basename>.txt, normalizing integers (remove leading + and leading zeros, treat -0 as 0). Use a single awk command to handle all files and create per-file outputs.

Act: bash

```bash
awk -v out=temp_workspace '
BEGIN{FS="[[:space:]]+"}
{
 fname=$0;
 cmd="basename \"" fname "\""
 cmd | getline bname; close(cmd);
 ints=out "/ints_" bname ".txt";
 verify=out "/verify_" bname ".txt";
 first_i[bname]=1; first_v[bname]=1;
 while( (getline line < fname) > 0 ){
  n=split(line, toks, /[[:space:]]+/);
  for(i=1;i<=n;i++){
    tok=toks[i];
    if(tok ~ /^\\+?[0-9]+$/ || tok ~ /^-[0-9]+$/){
       gsub(/^\\+/, "", tok);
       sign="";
       if(tok ~ /^-/){ sign="-"; num=substr(tok,2);} else num=tok;
       gsub(/^0+/, "", num);
       if(num=="") num="0";
       if(sign=="-" && num=="0") sign="";
       norm = sign num;
       if(first_i[bname]){ print norm > ints; first_i[bname]=0 } else { print norm >> ints }
    } else if(tok ~ /[[:alpha:]]/ && tok ~ /[0-9]/) {
       if(first_v[bname]){ print tok > verify; first_v[bname]=0 } else { print tok >> verify }
    }
  }
 }
 close(fname);
}
' temp_workspace/file_list.txt
```

