Think: Parse filenames in temp_workspace/log_filenames.txt, validate the YYYY-MM-DD date parts, write valid mappings to temp_workspace/filename_date_map.csv and invalid entries to temp_workspace/invalid_dates.txt.

Act: bash

```bash
awk '{
 fname=$0;
 if (length(fname)==18 && substr(fname,1,4)=="log_" && substr(fname,9,1)=="-" && substr(fname,12,1)=="-" && substr(fname,15,1)=="." && substr(fname,16,3)=="txt") {
   y = substr(fname,5,4) + 0;
   m = substr(fname,10,2) + 0;
   d = substr(fname,13,2) + 0;
   valid = 1;
   if (!(m>=1 && m<=12)) valid = 0;
   else {
     md = 31;
     if (m==4 || m==6 || m==9 || m==11) md = 30;
     else if (m==2) {
       if ((y%4==0 && y%100!=0) || (y%400==0)) md = 29; else md = 28;
     }
     if (!(d>=1 && d<=md)) valid = 0;
   }
   if (valid) {
     printf "%s,%04d-%02d-%02d\n", fname, y, m, d > "temp_workspace/filename_date_map.csv";
   } else {
     print fname > "temp_workspace/invalid_dates.txt";
   }
 } else if (fname != "") {
   print fname > "temp_workspace/invalid_dates.txt";
 }
}' temp_workspace/log_filenames.txt
