Think: Re-check each recorded file in temp_workspace/file_sizes.txt by calling stat on the path; write verified path<TAB>size lines to temp_workspace/ready_for_sum.txt and append any missing or size-mismatch records to temp_workspace/verification.log.

Act: bash

```bash
awk -F'\t' '{
 cmd = "stat -c %s \"" $1 "\" 2>/dev/null"
 cmd | getline actual
 close(cmd)
 if (actual == "") {
  print $0 "\tMISSING" >> "temp_workspace/verification.log"
 } else if (actual == $2) {
  print $1 "\t" actual >> "temp_workspace/ready_for_sum.txt"
 } else {
  print $1 "\t" $2 "\tACTUAL:" actual >> "temp_workspace/verification.log"
 }
}' temp_workspace/file_sizes.txt
