Think: For each npm path, check if it's executable and capture its version output (or note it's not executable). If no paths exist, ensure the versions file is created and empty.

Act: bash

```bash
awk '{
  cmd = "[ -x \"" $0 "\" ]";
  if (system(cmd) == 0) {
    vercmd = $0 " --version 2>&1";
    got = 0;
    while ((vercmd | getline line) > 0) {
      print $0 " : " line;
      got = 1;
    }
    close(vercmd);
    if (got == 0) print $0 " : (no output)";
  } else {
    print $0 " : not executable";
  }
}' temp_workspace/npm_locations.txt > temp_workspace/npm_versions.txt
```

